31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "city")
47	    @NotEmpty
48	    private String city;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a '+' followed by 8 to 15 digits)")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
69	    private Set<Pet> pets;
70	
71	    public String getAddress() {
72	        return this.address;
73	    }
74	
75	    public void setAddress(String address) {
76	        this.address = normalizeAddress(address);
77	    }
78	
79	    public String getCity() {
80	        return this.city;
81	    }
82	
83	    public void setCity(String city) {
84	        this.city = city;
85	    }
86	
87	    public String getTelephone() {
88	        return this.telephone;
89	    }
90	
91	    public void setTelephone(String telephone) {
92	        this.telephone = telephone;
93	    }
94	
95	    public String getEmail() {
96	        return this.email;
97	    }
98	
99	    public void setEmail(String email) {
100	        this.email = normalizeEmail(email);
101	    }
102	
103	    public LocalDate getRegistrationDate() {
104	        return this.registrationDate;
105	    }
106	
107	    public void setRegistrationDate(LocalDate registrationDate) {
108	        this.registrationDate = registrationDate;
109	    }
110	
111	    public String getCustomerCode() {
112	        return this.customerCode;
113	    }
114	
115	    public void setCustomerCode(String customerCode) {
116	        this.customerCode = customerCode;
117	    }
118	
119	    public Integer getNamesakeCount() {
120	        return this.namesakeCount;
121	    }
122	
123	    public void setNamesakeCount(Integer namesakeCount) {
124	        this.namesakeCount = namesakeCount;
125	    }
126	
127	    /**
128	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
129	     * source of truth for how an email is persisted, so inputs that differ only in letter case
130	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
131	     * (create and update, mapper or hand-copied) stores the same canonical value.
132	     *
133	     * @param email the raw email, possibly {@code null}
134	     * @return the lower-cased form, or {@code null} if the input was {@code null}
135	     */
136	    public static String normalizeEmail(String email) {
137	        return email == null ? null : email.toLowerCase();
138	    }
139	
140	    /**
141	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
142	     * truth for how a telephone is compared and persisted, so inputs that differ only in
143	     * formatting (spaces, dashes, brackets) are treated as the same number.
144	     *
145	     * <p>The rules are:
146	     * <ul>
147	     *   <li>spaces, dashes and brackets are stripped;</li>
148	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
149	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
150	     *       is dropped from the national digits;</li>
151	     *   <li>the result must have 8 to 15 digits after the {@code '+'}.</li>
152	     * </ul>
153	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
154	     * values are returned unchanged.
155	     *
156	     * @param telephone the raw telephone, possibly {@code null}
157	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
158	     *     valid E.164 number
159	     */
160	    public static String normalizeTelephone(String telephone) {
161	        if (telephone == null) {
162	            return null;
163	        }
164	        String trimmed = telephone.trim();
165	        boolean hasCountryCode = trimmed.startsWith("+");
166	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
167	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
168	        if (hasCountryCode) {
169	            stripped = stripped.substring(1);
170	        }
171	        if (!stripped.matches("\\d+")) {
172	            return null;
173	        }
174	        String digits;
175	        if (hasCountryCode) {
176	            digits = stripped;
177	        } else {
178	            if (stripped.startsWith("0")) {
179	                stripped = stripped.substring(1);
180	            }
181	            digits = "61" + stripped;
182	        }
183	        if (digits.length() < 8 || digits.length() > 15) {
184	            return null;
185	        }
186	        return "+" + digits;
187	    }
188	
189	    /**
190	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
191	     * upper-cased abbreviation.
192	     */
193	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
194	        "ST", "STREET",
195	        "RD", "ROAD",
196	        "AVE", "AVENUE");
197	
198	    /**
199	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
200	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
201	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
202	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
203	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
204	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
205	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
206	     * value. The transform is idempotent: a normalized address normalizes to itself.
207	     *
208	     * @param address the raw address, possibly {@code null}
209	     * @return the normalized form, or {@code null} if the input was {@code null}
210	     */
211	    public static String normalizeAddress(String address) {
212	        if (address == null) {
213	            return null;
214	        }
215	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
216	        if (collapsed.isEmpty()) {
217	            return collapsed;
218	        }
219	        String[] tokens = collapsed.split(" ");
220	        StringBuilder normalized = new StringBuilder(collapsed.length());
221	        for (int i = 0; i < tokens.length; i++) {
222	            if (i > 0) {
223	                normalized.append(' ');
224	            }
225	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
226	        }
227	        return normalized.toString();
228	    }
229	
230	    /**
231	     * Normalize a household field (such as last name or address) to its canonical form for
232	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
233	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
234	     * that differ only in letter case or spacing are treated as the same value.
235	     *
236	     * @param value the raw field value, possibly {@code null}
237	     * @return the normalized form, or {@code null} if the input was {@code null}
238	     */
239	    public static String normalizeHousehold(String value) {
240	        if (value == null) {
241	            return null;
242	        }
243	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
244	    }
245	
246	    /**
247	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
248	     * last name (compared case-insensitively with collapsed whitespace, see
249	     * {@link #normalizeHousehold(String)}) and the same normalized address (see
250	     * {@link #normalizeAddress(String)}). The value is deterministic in those two fields, so two
251	     * owners who share a household are assigned the same id. It is formatted {@code 'HH-<HEX12>'}
252	     * where {@code HEX12} is the first twelve upper-cased hex characters of the SHA-256 digest of
253	     * the normalized last name and address.
254	     *
255	     * @param lastName the owner's last name, possibly {@code null}
256	     * @param address the owner's address, possibly {@code null}
257	     * @return the household id, or {@code null} if either field is {@code null}
258	     */
259	    public static String householdId(String lastName, String address) {
260	        String normalizedLastName = normalizeHousehold(lastName);
261	        String normalizedAddress = normalizeAddress(address);
262	        if (normalizedLastName == null || normalizedAddress == null) {
263	            return null;
264	        }
265	        String key = normalizedLastName + "\n" + normalizedAddress;
266	        try {
267	            byte[] digest = MessageDigest.getInstance("SHA-256")
268	                .digest(key.getBytes(StandardCharsets.UTF_8));
269	            StringBuilder hex = new StringBuilder(digest.length * 2);
270	            for (byte b : digest) {
271	                hex.append(String.format("%02x", b));
272	            }
273	            return "HH-" + hex.substring(0, 12).toUpperCase();
274	        } catch (NoSuchAlgorithmException e) {
275	            // SHA-256 is a standard algorithm required to be present on every JVM.
276	            throw new IllegalStateException("SHA-256 not available", e);
277	        }
278	    }
279	
280	    /**
281	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
282	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
283	     * is the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}). The
284	     * value is deterministic in those two fields.
285	     *
286	     * @param customerCode the owner's customer code, possibly {@code null}
287	     * @param registrationDate the owner's registration date, possibly {@code null}
288	     * @return the membership number, or {@code null} if either field is {@code null}
289	     */
290	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
291	        if (customerCode == null || registrationDate == null) {
292	            return null;
293	        }
294	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
295	    }
296	
297	    /**
298	     * Build an owner's {@code membershipTier}, the derived tier based on the owner's namesake count
299	     * and whether an email is present. The value is {@code 'SILVER'} when {@code namesakeCount} is 0
300	     * and an email is present, and {@code 'BRONZE'} otherwise. The value is deterministic in those
301	     * two fields.
302	     *
303	     * @param namesakeCount the owner's namesake count, possibly {@code null}
304	     * @param email the owner's email, possibly {@code null}
305	     * @return {@code 'SILVER'} or {@code 'BRONZE'}
306	     */
307	    public static String membershipTier(Integer namesakeCount, String email) {
308	        boolean silver = namesakeCount != null && namesakeCount == 0 && email != null && !email.isEmpty();
309	        return silver ? "SILVER" : "BRONZE";
310	    }
311	
312	    /**
313	     * Fixed city-to-region table used by {@link #locality(String)} to derive an owner's locality,
314	     * keyed by the exact city name.
315	     */
316	    private static final Map<String, String> CITY_REGION = Map.of(
317	        "Sydney", "NSW",
318	        "Melbourne", "VIC",
319	        "Brisbane", "QLD");
320	
321	    /**
322	     * Derive an owner's {@code locality}, the canonical region for the owner's city, from the fixed
323	     * city-to-region table ({@code Sydney}->{@code NSW}, {@code Melbourne}->{@code VIC},
324	     * {@code Brisbane}->{@code QLD}). The value is deterministic in the city. A city not in the
325	     * table (including {@code null}) derives {@code 'UNKNOWN'}.
326	     *
327	     * @param city the owner's city, possibly {@code null}
328	     * @return the canonical region string, or {@code 'UNKNOWN'} when the city is not in the table
329	     */
330	    public static String locality(String city) {
331	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
332	    }
333	
334	    protected Set<Pet> getPetsInternal() {
335	        if (this.pets == null) {
336	            this.pets = new HashSet<>();
337	        }
338	        return this.pets;
339	    }
340	
341	    protected void setPetsInternal(Set<Pet> pets) {
342	        this.pets = pets;
343	    }
344	
345	    public List<Pet> getPets() {
346	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
347	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
348	        return Collections.unmodifiableList(sortedPets);
349	    }
350	
351	    public void setPets(List<Pet> pets) {
352	        this.pets = new HashSet<>(pets);
353	    }
354	
355	    public void addPet(Pet pet) {
356	        getPetsInternal().add(pet);
357	        pet.setOwner(this);
358	    }
359	
360	    /**
361	     * Return the Pet with the given name, or null if none found for this Owner.
362	     *
363	     * @param name to test
364	     * @return true if pet name is already in use
365	     */
366	    public Pet getPet(String name) {
367	        return getPet(name, false);
368	    }
369	
370	    /**
371	     * Return the Pet with the given name, or null if none found for this Owner.
372	     *
373	     * @param name to test
374	     * @return true if pet name is already in use
375	     */
376	    public Pet getPet(String name, boolean ignoreNew) {
377	        name = name.toLowerCase();
378	        for (Pet pet : getPetsInternal()) {
379	            if (!ignoreNew || !pet.isNew()) {
380	                String compName = pet.getName();
381	                compName = compName.toLowerCase();
382	                if (compName.equals(name)) {
383	                    return pet;
384	                }
385	            }
386	        }
387	        return null;
388	    }
389	
390	    public Pet getPet(Integer petId) {
391	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
392	    }
393	
