256	        if (owner.getRegistrationDate() == null) {
257	            owner.setRegistrationDate(LocalDate.now());
258	        }
259	        if (owner.isNew() && owner.getCustomerCode() == null) {
260	            owner.setCustomerCode(generateCustomerCode(owner));
261	        }
262	        if (owner.isNew() && owner.getNamesakeCount() == null) {
263	            owner.setNamesakeCount(countNamesakes(owner));
