268	    /**
269	     * Count the existing owners that, at the moment this owner is created, share its first name
270	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
271	     * it never counts itself. This value is deterministic given the current data, so it is computed
272	     * once at creation time and stored.
273	     */
274	    private Integer countNamesakes(Owner owner) {
275	        String firstName = owner.getFirstName();
276	        String lastName = owner.getLastName();
277	        if (firstName == null || lastName == null) {
278	            return 0;
279	        }
280	        return (int) ownerRepository.findAll().stream()
281	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
282	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
283	                && lastName.equalsIgnoreCase(existing.getLastName()))
284	            .count();
285	    }
