287	    /**
288	     * Build an owner's {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where
289	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} the
290	     * upper-cased first three letters of the last name, and {@code NNNN} a per-city, 4-digit
291	     * zero-padded sequence equal to one more than the number of owners already in that city
292	     * (e.g. {@code 'LON-SMI-0007'}).
293	     */
294	    private String generateCustomerCode(Owner owner) {
295	        String city = owner.getCity();
296	        String city3 = codePrefix(city);
297	        String last3 = codePrefix(owner.getLastName());
298	        long sequence = ownerRepository.findAll().stream()
299	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
300	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
301	            .count() + 1L;
302	        return String.format("%s-%s-%04d", city3, last3, sequence);
303	    }
