317	     */
318	    private void assertTelephoneIsUnique(Owner owner) {
319	        String normalized = Owner.normalizeTelephone(owner.getTelephone());
320	        if (normalized == null) {
321	            return;
322	        }
323	        boolean duplicate = ownerRepository.findAll().stream()
324	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
325	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
326	            .anyMatch(normalized::equals);
327	        if (duplicate) {
328	            throw new DuplicateTelephoneException(normalized);
329	        }
330	    }
331	
332	    /**
333	     * Enforce that no <em>other</em> owner already shares this owner's household, i.e. has the same
334	     * last name (compared case-insensitively with collapsed whitespace, see
335	     * {@link Owner#normalizeHousehold(String)}) and the same normalized address (see
336	     * {@link Owner#normalizeAddress(String)}), throwing {@link DuplicateHouseholdException} if one
337	     * does. The owner being saved is excluded by id. Callers skip this check when the request opted
338	     * in with {@code sharesHousehold}.
339	     */
340	    private void assertHouseholdIsUnique(Owner owner) {
341	        String lastName = Owner.normalizeHousehold(owner.getLastName());
342	        String address = Owner.normalizeAddress(owner.getAddress());
343	        if (lastName == null || address == null) {
344	            return;
345	        }
346	        boolean duplicate = ownerRepository.findAll().stream()
347	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
348	            .anyMatch(existing -> lastName.equals(Owner.normalizeHousehold(existing.getLastName()))
349	                && address.equals(Owner.normalizeAddress(existing.getAddress())));
350	        if (duplicate) {
351	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
352	        }
353	    }
