355	    /**
356	     * Enforce that the owner's city has not yet reached its capacity, throwing
357	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
358	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
359	     */
360	    private void assertCityHasCapacity(Owner owner) {
361	        String city = owner.getCity();
362	        if (city == null) {
363	            return;
364	        }
365	        long count = ownerRepository.findAll().stream()
366	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
367	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
368	            .count();
369	        if (count >= MAX_OWNERS_PER_CITY) {
370	            throw new CityAtCapacityException(city);
371	        }
372	    }
